     deleteFloorandRoom(){
  
      let idbuild = parseInt(this.buildingId) - 100
  
      let query1 = 'DELETE FROM sidsPrimaryFloorQuestion' +
        ' WHERE SclId = "' + this.schoolId + '"' +
        ' And BuildingId = "' + this.buildingId + '"' +
        ' And VistId = "' + this.vistId + '"';
  
      let query2 = 'DELETE FROM sidsPrimaryFloorSaveDatas' +
      ' WHERE SclId = "' + this.schoolId + '"' +
      ' And BuildIndx = "' + idbuild + '"' +
      ' And VistId = "' + this.vistId + '"';
  
      let query3 = 'DELETE FROM sidsPrimaryRoomSaves' +
      ' WHERE SclId = "' + this.schoolId + '"' +
      ' And BuildIndx = "' + idbuild + '"' +
      ' And VistId = "' + this.vistId + '"';
  
      let query4 = 'DELETE FROM newPrimaryRoomscommons' +
      ' WHERE SchlId = "' + this.schoolId + '"' +
      ' And BldgId = "' + this.buildingId + '"' +
      ' And VistId = "' + this.vistId + '"';

      let query5 = 'SELECT * FROM sidsPrimaryFloorQuestion' +
      ' WHERE SclId = "' + this.schoolId + '"' +
      ' And BuildingId = "' + this.buildingId + '"' +
      ' And VistId = "' + this.vistId + '"';
      
      return this.sqliteDB.getDataLocalDB(query5).then(floorData => {
        let sidsFloor = [];
        for (var i = 0; i < floorData.rows.length; i++) {
          sidsFloor.push(floorData.rows.item(i));
        }
        return this.sqliteDB.getDataLocalDB(query1).then(data => {
          return this.sqliteDB.getDataLocalDB(query2).then(data => {
            return this.sqliteDB.getDataLocalDB(query3).then(data => {
              return this.sqliteDB.getDataLocalDB(query4).then(data => {
                console.log("Floor and Room Deleted");
                if(this.dataList[0].BuildingIndex){
                  let params = {
                  "records": {
                    "IndexId": '',
                      "SchoolId": this.schoolId,
                      "VisitId": this.vistId,
                      "BuildId": this.buildingId,
                      "ToilBuildId": this.dataList[0].BuildingIndex,
                      // "No Delete Building"
                    }
                  }
                  let selectQuery = 'SELECT * FROM DeleteBuilding WHERE schoolId ="' + this.schoolId + '" And visitId ="' + this.vistId + '" And BuildId ="' + this.buildingId + '" And BuildIndxId ="'+ this.dataList[0].BuildingIndex +'"';
                  return this.sqliteDB.getDataLocalDB(selectQuery).then(data => {
                    if(data.rows.length == 0){
                      if(sidsFloor.length > 0 && sidsFloor[0].FloorIndx){
                        const datainsert = "INSERT INTO DeleteBuilding VALUES (?,?,?,?,?,?,?)";
                        this.sqliteDB.insert(datainsert, [null, this.schoolId, this.vistId, this.buildingId, JSON.stringify(params), this.dataList[0].BuildingIndex, 2
                        ]).then(insertres => {})
                      }
                    }
                  })
                  
                }
              })
            })
          })
        });
      });
    }
  
